import os

OUT = r"E:\BaiduNetdiskDownload\老梅面试\面试知识库\10_面试小礼包"

def write_answers(subdir, answers):
    for fname, answer in answers.items():
        path = os.path.join(OUT, subdir, fname)
        if not os.path.exists(path):
            print(f"  MISSING: {fname[:30]}")
            continue
        lines = open(path, encoding='utf-8').read().split('\n')
        ans_line = None
        for i, l in enumerate(lines):
            if l.startswith('###') and '答题示范' in l:
                ans_line = i
                break
        if ans_line is None:
            print(f"  NO ANS: {fname[:30]}")
            continue
        next_sec = len(lines)
        for i in range(ans_line+1, len(lines)):
            if lines[i].startswith('###'):
                next_sec = i
                break
        new_lines = lines[:ans_line+1] + ['', answer, ''] + lines[next_sec:]
        with open(path, 'w', encoding='utf-8') as f:
            f.write('\n'.join(new_lines))
        print(f"  DONE: {fname[:40]}")

